/**
 * @ohos/dsh-ontology/metrics — the small, reviewed calculations.
 *
 * Auto Ontology calls these Metrics: a reviewed SQL expression stored under a
 * term so every answer computes the same way. We do not let the model write
 * SQL, but the same discipline applies to date arithmetic. "How old am I" and
 * "how many days until the deadline" should be deterministic, versioned, and
 * return their inputs — not an LLM guess that drifts between turns.
 *
 * Keep this list deliberately small. A metric earns its place only when the
 * model would otherwise do calendar math or count rows by hand.
 */
import { OntologyError, search } from "./store.js";

const DAY_MS = 24 * 60 * 60 * 1000;

/**
 * @param {string} value - `YYYY-MM-DD`.
 * @returns {{year: number, month: number, day: number, ms: number}} parsed date.
 */
function parseDay(value) {
	const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(value ?? "").trim());
	if (match === null) throw new OntologyError(`date must be YYYY-MM-DD, got ${JSON.stringify(value)}`, "BAD_INPUT");
	const year = Number(match[1]);
	const month = Number(match[2]);
	const day = Number(match[3]);
	const ms = Date.UTC(year, month - 1, day);
	if (Number.isNaN(ms)) throw new OntologyError(`invalid date ${JSON.stringify(value)}`, "BAD_INPUT");
	return { year, month, day, ms };
}

/**
 * @param {Date|string|number} now - clock.
 * @returns {{year: number, month: number, day: number, ms: number}} today in UTC.
 */
function today(now) {
	const date = now instanceof Date ? now : new Date(now);
	return {
		year: date.getUTCFullYear(),
		month: date.getUTCMonth() + 1,
		day: date.getUTCDate(),
		ms: Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()),
	};
}

/**
 * @param {{db: object}} store - store handle.
 * @param {string} subject - entity name.
 * @param {string} predicate - predicate name.
 * @returns {object} the live fact.
 */
function onlyFact(store, subject, predicate) {
	const rows = search(store, { subject, predicate, limit: 1 });
	if (rows.length === 0) {
		throw new OntologyError(`no live ${predicate} for ${JSON.stringify(subject)}; record it before asking for the metric`, "NOT_FOUND");
	}
	return rows[0];
}

/** @type {Record<string, {about: string, run: (store: object, input: object) => object}>} */
export const METRICS = Object.freeze({
	age: {
		about: "Age in whole years from a birthday with a year (YYYY-MM-DD).",
		run: (store, input) => {
			const fact = onlyFact(store, input.subject, "birthday");
			const birthday = parseDay(fact.object);
			const now = today(input.now);
			let value = now.year - birthday.year;
			if (now.month < birthday.month || (now.month === birthday.month && now.day < birthday.day)) value--;
			return { name: "age", value, unit: "years", rule: "age/v1", inputs: [fact] };
		},
	},
	days_until: {
		about: "Whole days from today to a deadline (negative when it has passed).",
		run: (store, input) => {
			const predicate = String(input.predicate ?? "deadline").trim() || "deadline";
			const fact = onlyFact(store, input.subject, predicate);
			const target = parseDay(fact.object);
			const value = Math.round((target.ms - today(input.now).ms) / DAY_MS);
			return { name: "days_until", value, unit: "days", rule: "days_until/v1", inputs: [fact] };
		},
	},
	days_since: {
		about: "Whole days since a meeting/event (negative when it is in the future).",
		run: (store, input) => {
			const predicate = String(input.predicate ?? "met_on").trim() || "met_on";
			const fact = onlyFact(store, input.subject, predicate);
			const event = parseDay(fact.object);
			const value = Math.round((today(input.now).ms - event.ms) / DAY_MS);
			return { name: "days_since", value, unit: "days", rule: "days_since/v1", inputs: [fact] };
		},
	},
	count: {
		about: "Number of live facts for a predicate, optionally for one subject.",
		run: (store, input) => {
			const predicate = String(input.predicate ?? "").trim();
			if (predicate.length === 0) throw new OntologyError("count requires a predicate", "BAD_INPUT");
			const rows = search(store, { subject: input.subject, predicate, limit: 100 });
			return { name: "count", value: rows.length, unit: "facts", rule: "count/v1", inputs: rows };
		},
	},
});

/**
 * Run one named metric.
 * @param {{db: object}} store - store handle.
 * @param {{name?: string, subject?: string, predicate?: string, now?: Date|string|number}} input - metric request.
 * @returns {object} metric result with value, unit, rule, inputs.
 */
export function runMetric(store, input) {
	const name = String(input.name ?? "").trim();
	const metric = METRICS[name];
	if (metric === undefined) {
		throw new OntologyError(`unknown metric ${JSON.stringify(name)}; use ${Object.keys(METRICS).join(" | ")}`, "BAD_INPUT");
	}
	return metric.run(store, {
		subject: String(input.subject ?? "self").trim() || "self",
		predicate: input.predicate,
		now: input.now ?? new Date(),
	});
}

/** @returns {string} one-line metric list for the tool description. */
export function describeMetrics() {
	return Object.entries(METRICS).map(([name, metric]) => `${name}: ${metric.about}`).join("; ");
}
